  "instagramConnect.webhookHintGetVsPost": "Penting: Log GET = verifikasi webhook saja. Pesan DM baru masuk ke Live Chat bila Meta mengirim POST. Itu hanya terjadi jika Webhook Instagram (bukan hanya WhatsApp) sudah di-set + subscribe messages. Setelah set, kirim pesan tes dari akun Instagram lain ke akun bisnis Anda; di Logs cari \"Webhook POST: object= instagram\".",
