  "instagramConnect.webhookHintDescription": "In Meta Developer → Webhooks → Instagram: set Callback URL (same as below), Verify Token (same as below), then subscribe to messages. Without this, Meta will not send DMs to the app.",
  "instagramConnect.webhookHintGetVsPost": "Important: A GET log is only webhook verification. DMs appear in Live Chat only when Meta sends a POST. That only happens if the Instagram webhook (not just WhatsApp) is configured and subscribed to messages. After configuring, send a test DM from another Instagram account to your business account; in Logs look for \"Webhook POST: object= instagram\".",
  "instagramConnect.webhookInboundBody": "In Meta Developer → App (Vialdi ID) → Instagram → Configuration → Webhook: set Callback URL and Verify Token below, then Verify and Save. Then subscribe to \"messages\". Without this, DMs to your Instagram account will not reach the app and there will be no instagram-webhook logs.",
